test("recovery with ONE survivor: the last gated lane can adopt a plan alone", () => {
  const f = fleet(":memory:", ["L1", "L2"]);
  try {
    const id = episode(f, true);
    c.attest(f.s, id, "L2", "rt-L2", "STOPPED", "receipt-L2", "died in discussion");
    const before = gate.status(f.s, id);
    assert.deepEqual(before.required, ["L1"]);
    assert.equal(before.state, "PENDING", "one lane left is a plan the lane can still vote, not a dead end");
    const plan = JSON.stringify({ L1: { role: "everything", slice: "the tree" }, L2: { role: "gone", slice: "the tree" } });
    adoptPlan(f, id, "L1", plan, ["L1"]);
    const after = gate.status(f.s, id, f.peers.L1!);
    assert.equal(after.state, "CLEARED");
    assert.equal(gate.refusal(f.s, f.peers.L1!, id, "write"), null);
  } finally { f.s.close(); }
});
EOF
